#include <iostream>
#include <cstdio>
#include <cmath>
#include <cstring>
#include <algorithm>
using namespace std;

int total_n, total_k, modulus;
long long fact[250003], inv_fact[250003];
long long memo_dp[27][250003];

int get_lowbit_value(int x) { return x & (-x); }

long long power_mod(long long base, int exponent) {
    long long result = 1;
    while (exponent > 0) {
        if (exponent & 1) result = (result * base) % modulus;
        base = (base * base) % modulus;
        exponent >>= 1;
    }
    return result;
}

void precompute() {
    fact[0] = 1;
    for (int i = 1; i <= total_n; ++i)
        fact[i] = (fact[i - 1] * i) % modulus;
    inv_fact[total_n] = power_mod(fact[total_n], modulus - 2);
    for (int i = total_n - 1; i >= 0; --i)
        inv_fact[i] = (inv_fact[i + 1] * (i + 1)) % modulus;
}

long long recurse(int x, int s) {
    if (memo_dp[x][s] != -1) return memo_dp[x][s];
    if (s == 0) return memo_dp[x][s] = (fact[total_n] * fact[total_k] % modulus) * inv_fact[total_k - x] % modulus;
    int remaining = s - get_lowbit_value(s);
    long long sum_result = 0;
    for (int t = remaining; t; t = (t - 1) & remaining)
        sum_result = (sum_result + recurse(x + 1, t) * inv_fact[s - t]) % modulus;
    sum_result = (sum_result + recurse(x + 1, 0) * inv_fact[s]) % modulus;
    return memo_dp[x][s] = sum_result;
}

int main() {
    scanf("%d %d %d", &total_n, &total_k, &modulus);
    precompute();
    long long answer = power_mod(total_k, total_n);
    if (total_n % 2 == 0) {
        memset(memo_dp, -1, sizeof(memo_dp));
        answer = (answer - recurse(0, total_n) + modulus) % modulus;
    }
    printf("%lld", answer);
    return 0;
}
